// The cast: 13 chibi characters cut from the sticker sheets. Pictures live in public/stickers/<who>/<category>-<n>.webp
// and stickerManifest.js (generated by tools/export_stickers.py) lists what each character has.
import MANIFEST from "./stickerManifest";

const V = "?v=1"; // bump when sticker art changes so browsers never mix old art with new code
export const CHARS = { asta: "Asta", luffy: "Luffy", naruto: "Naruto", jinwoo: "Jin-Woo", goku: "Goku", kakashi: "Kakashi", zoro: "Zoro", gojo: "Gojo", tanjiro: "Tanjiro", killua: "Killua", vegeta: "Vegeta", zenitsu: "Zenitsu", bakugo: "Bakugo" };
export const ALL = Object.keys(CHARS).filter((k) => MANIFEST[k]);
export const DAY_ORDER = ["naruto", "zoro", "luffy", "goku", "tanjiro", "gojo", "asta"]; // Sun..Sat
export const dayChar = (d = new Date()) => (ALL.includes(DAY_ORDER[d.getDay()]) ? DAY_ORDER[d.getDay()] : ALL[d.getDay() % ALL.length]);
export const accent = { asta: "#e8b84a", luffy: "#e0443a", naruto: "#ff9a1f", jinwoo: "#7a5cff", goku: "#ff8a00", kakashi: "#8da2c0", zoro: "#3fae4a", gojo: "#7fc6ff", tanjiro: "#17a57a", killua: "#9fb7ff", vegeta: "#2f5fd0", zenitsu: "#ffc21a", bakugo: "#ff6a2a" };

// What each app "scene" looks like in sticker terms: the first categories are preferred.
export const SCENE_CATS = {
  lift: ["lift", "sport"], sad: ["cry", "confused", "think", "angry", "smug"], drink: ["drink", "boba"], eat: ["eat", "noodles", "burger", "rice", "pizza", "boba"],
  scale: ["think", "smug", "confused"], walk: ["sport", "hype"], task: ["laptop", "study", "read"], plan: ["study", "read", "laptop", "think"],
  chart: ["thumbs", "smug", "laptop"], health: ["bath", "chill", "peace", "sleep"], chef: ["noodles", "eat", "rice", "burger"],
  habit: ["thumbs", "lift", "hype"], cheer: ["hype", "laugh", "party", "thumbs"], wave: ["laugh", "hype", "peace", "thumbs"],
  powerup: ["power", "angry", "lift", "hype"], victory: ["party", "hype", "thumbs", "laugh"], levelup: ["party", "hype", "laugh"], fight: ["power", "angry", "lift", "sport"],
  sleep: ["sleep", "chill"], game: ["game", "laptop"], love: ["love", "laugh"], cool: ["cool", "smug"], shock: ["shock", "confused"], angry: ["angry"], think: ["think", "confused", "smug"],
};
const GENERIC = ["hype", "laugh", "thumbs", "peace", "smug", "think"];

function hash(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) h = Math.imul(h ^ str.charCodeAt(i), 16777619); return h >>> 0; }
const url = (who, name) => `${import.meta.env.BASE_URL}stickers/${who}/${name}.webp${V}`;

/** A sticker for these categories. `seed` keeps the pick stable between renders; pass a changing seed to vary it. */
export function pickSticker(who, cats, seed = 0) {
  const set = MANIFEST[who] || MANIFEST[ALL[0]] || {};
  const w = MANIFEST[who] ? who : ALL[0];
  for (const group of [cats, GENERIC]) {
    const pool = (group || []).flatMap((c) => set[c] || []);
    if (pool.length) { const p = pool[Math.abs(typeof seed === "number" ? seed : hash(String(seed))) % pool.length]; return { src: url(w, p[0]), w: p[1], h: p[2], name: p[0] }; }
  }
  const any = Object.values(set).flat()[0];
  return any ? { src: url(w, any[0]), w: any[1], h: any[2], name: any[0] } : { src: "", w: 1, h: 1, name: "" };
}
export const sprite = (who, scene, seed = 0) => pickSticker(who, SCENE_CATS[scene] || [scene], typeof seed === "string" ? hash(seed) : seed).src;
export const stickerFor = (who, scene, seed = 0) => pickSticker(who, SCENE_CATS[scene] || [scene], typeof seed === "string" ? hash(seed) : seed);
export const hasCat = (who, cat) => !!(MANIFEST[who] && MANIFEST[who][cat]);
export const preload = (who, scenes) => scenes.forEach((s) => { const i = new Image(); i.src = sprite(who, s); });

/** Direct URL of one sticker by its album id parts, e.g. stickerUrl("zoro", "hype-0"). */
export const stickerUrl = (who, name) => url(who, name);
export const stickerList = () => MANIFEST;
